import{_ as l,a0 as o,w as p,s as u,I as n,x as s,a1 as e,A as i,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"使用 Quagga 实现 Linux 动态路由 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Quagga 实现 Linux 动态路由 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Quagga 实现 Linux 动态路由 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Quagga 实现 Linux 动态路由 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180308 Dynamic Linux Routing with Quagga","title":"使用 Quagga 实现 Linux 动态路由","tag":"201806","desc":""},"relativePath":"201806/20180308 Dynamic Linux Routing with Quagga.md","filePath":"[post].md"}'),r={name:"201806/20180308 Dynamic Linux Routing with Quagga.md"};function g(f,a,b,c,h,k){const t=o("Link");return p(),u("div",null,[a[24]||(a[24]=n("h1",{id:"使用-quagga-实现-linux-动态路由",tabindex:"-1"},[s("使用 Quagga 实现 Linux 动态路由 "),n("a",{class:"header-anchor",href:"#使用-quagga-实现-linux-动态路由","aria-label":"Permalink to “使用 Quagga 实现 Linux 动态路由”"},"​")],-1)),a[25]||(a[25]=n("blockquote",null,[n("p",null,"学习如何使用 Quagga 套件的路由协议去管理动态路由。")],-1)),a[26]||(a[26]=n("p",null,[n("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/network_visualization.png?itok=P3Ve7eO1",alt:"network",title:"network"})],-1)),n("p",null,[a[2]||(a[2]=s("迄今为止，本系列文章中，我们已经在 ",-1)),e(t,{href:"https://linux.cn/article-9657-1.html"},{default:i(()=>[...a[0]||(a[0]=[s("Linux 局域网路由新手指南：第 1 部分",-1)])]),_:1}),a[3]||(a[3]=s(" 中学习了复杂的 IPv4 地址，在  ",-1)),e(t,{href:"https://linux.cn/article-9675-1.html"},{default:i(()=>[...a[1]||(a[1]=[s("Linux 局域网路由新手指南：第 2 部分",-1)])]),_:1}),a[4]||(a[4]=s(" 中学习了如何去手工创建静态路由。",-1))]),n("p",null,[a[6]||(a[6]=s("今天，我们继续使用 ",-1)),e(t,{href:"https://www.quagga.net/"},{default:i(()=>[...a[5]||(a[5]=[s("Quagga",-1)])]),_:1}),a[7]||(a[7]=s(" 去管理动态路由，这是一个安装完后就不用理它的的软件。Quagga 是一个支持 OSPFv2、OSPFv3、RIP v1 和 v2、RIPng、以及 BGP-4 的路由协议套件，并全部由 zebra 守护程序管理。",-1))]),a[27]||(a[27]=d(`<p>OSPF 的意思是<ruby>最短路径优先<rt>Open Shortest Path First</rt></ruby>。OSPF 是一个内部网关协议（IGP）;它可以用在局域网和跨因特网的局域网互联中。在你的网络中的每个 OSPF 路由器都包含整个网络的拓扑，并计算通过该网络的最短路径。OSPF 会通过多播的方式自动对外传播它检测到的网络变化。你可以将你的网络分割为区域，以保持路由表的可管理性；每个区域的路由器只需要知道离开它的区域的下一跳接口地址，而不用记录你的网络的整个路由表。</p><p>RIP，即路由信息协议，是一个很老的协议，RIP 路由器向网络中周期性多播它的整个路由表，而不是像 OSPF 那样只多播网络的变化。RIP 通过跳数来测量路由，任何超过 15 跳的路由它均视为不可到达。RIP 设置很简单，但是 OSPF 在速度、效率以及弹性方面更佳。</p><p>BGP-4 是边界网关协议版本 4。这是用于因特网流量路由的外部网关协议（EGP）。你不会用到 BGP 协议的，除非你是因特网服务提供商。</p><h3 id="准备使用-ospf" tabindex="-1">准备使用 OSPF <a class="header-anchor" href="#准备使用-ospf" aria-label="Permalink to “准备使用 OSPF”">​</a></h3><p>在我们的小型 KVM 测试实验室中，用两台虚拟机表示两个不同的网络，然后将另一台虚拟机配置为路由器。创建两个网络：net1 是 192.168.110.0/24 ，而 net2 是 192.168.120.0/24。启用 DHCP 是明智的，否则你要分别进入这三个虚拟机，去为它们设置静态地址。Host 1 在 net1 中，Host 2 在 net2 中，而路由器同时与这两个网络连接。设置 Host 1 的网关地址为 192.168.110.126，Host 2 的网关地址为 192.168.120.136。</p><ul><li>Host 1： 192.168.110.125</li><li>Host 2：192.168.120.135</li><li>Router：192.168.110.126 和 192.168.120.136</li></ul><p>在路由器上安装 Quagga。在大多数 Linux 中它是 quagga 软件包。在 Debian 上还有一个单独的文档包 quagga-doc。取消 <code>/etc/sysctl.conf</code> 配置文件中如下这一行的注释去启用包转发功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>net.ipv4.ip_forward=1</span></span></code></pre></div><p>然后，运行 <code>sysctl -p</code> 命令让变化生效。</p><h3 id="配置-quagga" tabindex="-1">配置 Quagga <a class="header-anchor" href="#配置-quagga" aria-label="Permalink to “配置 Quagga”">​</a></h3><p>查看你的 Quagga 包中的示例配置文件，比如，<code>/usr/share/doc/quagga/examples/ospfd.conf.sample</code>。除非你的 Linux 版本按你的喜好做了创新，否则，一般情况下配置文件应该在 <code>/etc/quagga</code> 目录中。大多数 Linux 版本在这个目录下有两个文件，<code>vtysh.conf</code>  和 <code>zebra.conf</code>。它们提供了守护程序运行所需要的最小配置。除非你的发行版做了一些特殊的配置，否则，zebra 总是首先运行，当你启动 ospfd 的时候，它将自动启动。Debian/Ubuntu 是一个特例，稍后我们将会说到它。</p><p>每个路由器守护程序将读取它自己的配置文件，因此，我们必须创建 <code>/etc/quagga/ospfd.conf</code>，并输入如下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>!/etc/quagga/ospfd.conf</span></span>
<span class="line"><span>hostname router1</span></span>
<span class="line"><span>log file /var/log/quagga/ospfd.log</span></span>
<span class="line"><span>router ospf</span></span>
<span class="line"><span>  ospf router-id 192.168.110.15</span></span>
<span class="line"><span>  network 192.168.110.0/0 area 0.0.0.0</span></span>
<span class="line"><span>  network 192.168.120.0/0 area 0.0.0.0</span></span>
<span class="line"><span>access-list localhost permit 127.0.0.1/32</span></span>
<span class="line"><span>access-list localhost deny any</span></span>
<span class="line"><span>line vty</span></span>
<span class="line"><span>  access-class localhost</span></span></code></pre></div><p>你可以使用感叹号（<code>!</code>）或者井号（<code>#</code>）去注释掉这些行。我们来快速浏览一下这些选项。</p><ul><li><code>hostname</code> 可以是你希望的任何内容。这里不是一般意义上的 Linux 主机名，但是，当你使用 <code>vtysh</code> 或者 <code>telnet</code> 登入时，你将看到它们。</li><li><code>log file</code> 是你希望用于保存日志的任意文件。</li><li><code>router</code> 指定路由协议。</li><li><code>ospf router-id</code> 是任意的 32 位数字。使用路由器的一个 IP 地址就是很好的选择。</li><li><code>network</code> 定义你的路由器要通告的网络。</li><li><code>access-list</code> 限制 <code>vtysh</code> 登入，它是 Quagga 命令行 shell，它允许本地机器登入，并拒绝任何远程管理。</li></ul><h3 id="debian-ubuntu" tabindex="-1">Debian/Ubuntu <a class="header-anchor" href="#debian-ubuntu" aria-label="Permalink to “Debian/Ubuntu”">​</a></h3><p>在你启动守护程序之前，Debian/Ubuntu 相对其它的 Debian 衍生版可能多需要一步到多步。编辑 <code>/etc/quagga/daemons</code> ，除了 <code>zebra=yes</code> 和 <code>ospfd=yes</code> 外，使其它所有的行的值为 <code>no</code>。</p><p>然后，在 Debian 上运行 <code>ospfd</code> 去启动 Quagga：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl start quagga</span></span></code></pre></div><p>在大多数的其它 Linux 上，包括 Fedora 和 openSUSE，用如下命令启动 <code>ospfd</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl start ospfd</span></span></code></pre></div><p>现在，Host 1 和 Host 2 将可以互相 ping 通对方和路由器。</p><p>这里用了许多篇幅去描述非常简单的设置。在现实中，路由器将连接两个交换机，然后为连接到这个交换机上的所有电脑提供一个网关。你也可以在你的路由器上添加更多的网络接口，这样你的路由器就可以为更多的网络提供路由服务，或者也可以直接连接到其它路由器上，或者连接到连接其它路由器的骨干网络上。</p><p>你或许不愿意如此麻烦地手工配置网络接口。最简单的方法是使用你的 DHCP 服务器去宣告你的路由器。如果你使用了 Dnsmasq，那么你就有了一个 DHCP 和 DNS 的一体化解决方案。</p>`,24)),n("p",null,[a[9]||(a[9]=s("还有更多的配置选项，比如，加密的密码保护。更多内容请查看 ",-1)),e(t,{href:"https://www.quagga.net/"},{default:i(()=>[...a[8]||(a[8]=[s("Quagga 路由套件",-1)])]),_:1}),a[10]||(a[10]=s(" 的官方文档。",-1))]),a[28]||(a[28]=n("hr",null,null,-1)),n("p",null,[a[12]||(a[12]=s("via: ",-1)),e(t,{href:"https://www.linux.com/learn/intro-to-linux/2018/3/dynamic-linux-routing-quagga"},{default:i(()=>[...a[11]||(a[11]=[s("https://www.linux.com/learn/intro-to-linux/2018/3/dynamic-linux-routing-quagga",-1)])]),_:1})]),n("p",null,[a[16]||(a[16]=s("作者：",-1)),e(t,{href:"https://www.linux.com/users/cschroder"},{default:i(()=>[...a[13]||(a[13]=[s("CARLA SCHRODER",-1)])]),_:1}),a[17]||(a[17]=s(" 译者：",-1)),e(t,{href:"https://github.com/qhwdw"},{default:i(()=>[...a[14]||(a[14]=[s("qhwdw",-1)])]),_:1}),a[18]||(a[18]=s(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:i(()=>[...a[15]||(a[15]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[21]||(a[21]=s("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[19]||(a[19]=[s("LCTT",-1)])]),_:1}),a[22]||(a[22]=s(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:i(()=>[...a[20]||(a[20]=[s("Linux中国",-1)])]),_:1}),a[23]||(a[23]=s(" 荣誉推出",-1))])])}const P=l(r,[["render",g]]);export{w as __pageData,P as default};
